<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/auth.php';require_admin();
$page_title='Activity Logs';$rows=$pdo->query("SELECT a.id,u.name,a.action,a.entity_type,a.entity_id,a.created_at FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC")->fetchAll();include __DIR__.'/../includes/header.php';?>
<div class="admin-layout py-3"><?php include __DIR__.'/../includes/sidebar.php';?><section><div class="mb-4"><div class="text-primary fw-bold">MANAGEMENT</div><h2 class="section-title">Activity Logs</h2></div><div class="glass-panel table-wrap"><table class="table align-middle"><thead><tr><?php if($rows): foreach(array_keys($rows[0]) as $h):?><th><?=e(ucwords(str_replace('_',' ',$h)))?></th><?php endforeach; endif;?></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($row as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section></div><?php include __DIR__.'/../includes/footer.php';?>